#!/usr/bin/env node
// Builds the TEST FIXTURES in this folder: synthetic candles in the exact shape the
// `market-data` Edge Function returns, for js/core/market.js mock mode
// (localStorage['tts-market-mock'] = '1' on localhost). They are NOT real market data and are
// never shown outside mock mode.
//
//   node tests/fixtures/market/build-fixtures.mjs
//
// Deterministic: realisticMarket() (regime switches, volatility clustering, fat tails, gaps)
// with fixed seeds. Timestamps are candle open times (ms UTC) on real interval boundaries,
// ending on Friday 25 Sep 2026: daily candles at 00:00 UTC (weekdays only for SPY and EUR-USD),
// weekly candles keyed by Monday 00:00 UTC. The last ~70 weekly candles are aggregated from the
// daily fixture, so daily and weekly agree where they overlap.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { realisticMarket, roundPrice } from '../../../js/core/data.js';

const DIR = path.dirname(fileURLToPath(import.meta.url));
const DAY = 86_400_000;
const END_DAY = Date.UTC(2026, 8, 25); // Fri 25 Sep 2026
const NOTE =
  'TEST FIXTURE - synthetic candles generated by tests/fixtures/market/build-fixtures.mjs with realisticMarket(). ' +
  "NOT real market data. Served only in mock mode (localStorage['tts-market-mock'] = '1' on localhost).";
const ATTRIBUTION = 'Test fixture: synthetic candles, not real prices';

// daily / weekly: generator settings; band: plausible [min, max] for the daily fixture's prices;
// wStart: plausible first weekly close (Mar 2015). Seeds are searched deterministically until
// the synthetic path stays inside the bands, so the charts look like the market they stand for.
const MARKETS = {
  'BTC-USD': { name: 'Bitcoin', class: 'crypto', decimals: 2, weekdays: false, daily: { vol: 0.021, drift: 0.0002, start: 64000, seed: 101 }, band: [38000, 135000], weekly: { vol: 0.075, drift: 0.0105, seed: 102 }, wStart: [150, 900], volume: 22000, fxNoVolume: false },
  'ETH-USD': { name: 'Ethereum', class: 'crypto', decimals: 2, weekdays: false, daily: { vol: 0.027, drift: 0.0001, start: 2900, seed: 201 }, band: [1300, 5600], weekly: { vol: 0.09, drift: 0.0085, seed: 202 }, wStart: [0.4, 25], volume: 310000, fxNoVolume: false },
  SPY: { name: 'S&P 500 ETF', class: 'etf', decimals: 2, weekdays: true, daily: { vol: 0.008, drift: 0.0003, start: 560, seed: 301 }, band: [440, 760], weekly: { vol: 0.019, drift: 0.0022, seed: 302 }, wStart: [150, 260], weeklyBand: [120, 690], volume: 68_000_000, fxNoVolume: false },
  'EUR-USD': { name: 'Euro / US dollar', class: 'fx', decimals: 5, weekdays: true, daily: { vol: 0.0038, drift: 0, start: 1.085, seed: 401 }, band: [1.0, 1.2], weekly: { vol: 0.009, drift: 0, seed: 402, regime: 'range' }, wStart: [1.02, 1.25], weeklyBand: [0.95, 1.3], volume: 0, fxNoVolume: true },
};

/** First seed (seed, seed + 1000, …) whose series satisfies ok(). */
function search(seed, make, ok) {
  for (let k = 0; k < 400; k++) {
    const s = seed + k * 1000;
    const out = make(s);
    if (ok(out)) return out;
  }
  throw new Error(`no seed found from ${seed}`);
}

const mondayOf = (ms) => ms - ((new Date(ms).getUTCDay() + 6) % 7) * DAY;

function dailyTimes(n, weekdays) {
  const out = [];
  for (let t = END_DAY; out.length < n; t -= DAY) {
    const dow = new Date(t).getUTCDay();
    if (weekdays && (dow === 0 || dow === 6)) continue;
    out.push(t);
  }
  return out.reverse();
}

function finish(candles, m) {
  return candles.map((k) => {
    const o = roundPrice(k.o, m.decimals);
    const c = roundPrice(k.c, m.decimals);
    const h = Math.max(roundPrice(k.h, m.decimals), o, c);
    const l = Math.min(roundPrice(k.l, m.decimals), o, c);
    return { t: k.t, o, h, l, c, v: m.fxNoVolume ? 0 : Math.max(1, Math.round((k.v / 1000) * m.volume)) };
  });
}

function write(name, body) {
  const file = path.join(DIR, `${name}.json`);
  fs.writeFileSync(file, `${JSON.stringify(body)}\n`);
  console.log(`${name}.json  ${body.candles ? `${body.candles.length} candles` : ''}  ${(fs.statSync(file).size / 1024).toFixed(1)} KB`);
}

const fixture = (symbol, interval, candles) => ({ _note: NOTE, fixture: true, symbol, interval, source: 'fixture', attribution: ATTRIBUTION, delayed: true, candles });

const dailyBySymbol = {};
for (const [symbol, m] of Object.entries(MARKETS)) {
  // Daily: 500 candles.
  const times = dailyTimes(500, m.weekdays);
  const inBand = (cs, [lo, hi]) => cs.every((k) => k.l >= lo && k.h <= hi);
  const d = search(
    m.daily.seed,
    (seed) => realisticMarket({ seed, count: times.length, start: m.daily.start, vol: m.daily.vol, drift: m.daily.drift, regime: 'mixed' }),
    (cs) => inBand(cs, m.band),
  );
  const daily = finish(d.map((k, i) => ({ ...k, t: times[i] })), m);
  dailyBySymbol[symbol] = daily;
  write(`${symbol}_1d`, fixture(symbol, '1d', daily));

  // Weekly: 600 candles. Weeks fully covered by the daily fixture are aggregated from it; the
  // older weeks are synthetic weekly candles scaled to lead into the first aggregated week.
  const byWeek = new Map();
  for (const k of daily) {
    const w = mondayOf(k.t);
    const g = byWeek.get(w);
    if (!g) byWeek.set(w, { t: w, o: k.o, h: k.h, l: k.l, c: k.c, v: k.v, days: 1 });
    else {
      g.h = Math.max(g.h, k.h);
      g.l = Math.min(g.l, k.l);
      g.c = k.c;
      g.v += k.v;
      g.days++;
    }
  }
  const firstMonday = mondayOf(daily[0].t);
  const weeksFromDaily = [...byWeek.values()].filter((g) => g.t > firstMonday || daily[0].t === firstMonday).map(({ days, ...k }) => k);
  const nSynth = 600 - weeksFromDaily.length;
  const w = search(
    m.weekly.seed,
    (seed) => {
      const raw = realisticMarket({ seed, count: nSynth, start: 100, vol: m.weekly.vol, drift: m.weekly.drift, regime: m.weekly.regime || 'mixed' });
      const f = weeksFromDaily[0].o / raw[raw.length - 1].c;
      return raw.map((k) => ({ ...k, o: k.o * f, h: k.h * f, l: k.l * f, c: k.c * f }));
    },
    (cs) => cs[0].c >= m.wStart[0] && cs[0].c <= m.wStart[1] && (!m.weeklyBand || inBand(cs, m.weeklyBand)),
  );
  const k0 = 1;
  const t0 = weeksFromDaily[0].t - nSynth * 7 * DAY;
  const synth = finish(w.map((k, i) => ({ o: k.o * k0, h: k.h * k0, l: k.l * k0, c: k.c * k0, v: k.v * (m.weekdays ? 5 : 7), t: t0 + i * 7 * DAY })), m);
  write(`${symbol}_1w`, fixture(symbol, '1w', [...synth, ...weeksFromDaily]));
}

// Intraday BTC-USD for live / replay tests: 300 candles ending 25 Sep 2026 20:00 UTC.
for (const [interval, step, vol, seed] of [['1m', 60_000, 0.0009, 501], ['5m', 300_000, 0.002, 502]]) {
  const m = MARKETS['BTC-USD'];
  const last = dailyBySymbol['BTC-USD'][dailyBySymbol['BTC-USD'].length - 1];
  const endT = END_DAY + 20 * 3_600_000;
  const cs = realisticMarket({ seed, count: 300, start: (last.o + last.c) / 2, vol, regime: 'mixed' });
  write(`BTC-USD_${interval}`, fixture('BTC-USD', interval, finish(cs.map((k, i) => ({ ...k, v: k.v / 40, t: endT - (300 - i) * step })), m)));
}

write('catalog', {
  _note: NOTE,
  fixture: true,
  status: 'online',
  symbols: [
    { id: 'BTC-USD', name: 'Bitcoin', class: 'crypto', decimals: 2, intervals: ['1m', '5m', '1d', '1w'], live: true, delayed: false },
    { id: 'ETH-USD', name: 'Ethereum', class: 'crypto', decimals: 2, intervals: ['1d', '1w'], live: false, delayed: true },
    { id: 'SPY', name: 'S&P 500 ETF', class: 'etf', decimals: 2, intervals: ['1d', '1w'], live: false, delayed: true },
    { id: 'EUR-USD', name: 'Euro / US dollar', class: 'fx', decimals: 5, intervals: ['1d', '1w'], live: false, delayed: true },
  ],
});
